def get_month(day_of_year):
    # 2023 is not a leap year
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    month = 1
    accumulated_days = 0
    for days in days_in_months:
        if day_of_year <= accumulated_days + days:
            return month
        accumulated_days += days
        month += 1
    return 12

def parse_volume(volume_str):
    if volume_str is None:
        return None
    if volume_str.startswith('<'):
        val = volume_str[1:]
        if val.endswith('k'): return (0, float(val[:-1]) * 1000)
        if val.endswith('m'): return (0, float(val[:-1]) * 1000000)
    if volume_str.startswith('>'):
        val = volume_str[1:]
        if val.endswith('k'): return (float(val[:-1]) * 1000, float('inf'))
        if val.endswith('m'): return (float(val[:-1]) * 1000000, float('inf'))
    if '-' in volume_str:
        low, high = volume_str.split('-')
        def to_val(v):
            if v.endswith('k'): return float(v[:-1]) * 1000
            if v.endswith('m'): return float(v[:-1]) * 1000000
            return float(v)
        return (to_val(low), to_val(high))
    return None

def parse_fraud(fraud_str):
    if fraud_str is None:
        return None
    if fraud_str.startswith('<'):
        val = fraud_str[1:].replace('%', '')
        return (0, float(val))
    if fraud_str.startswith('>'):
        val = fraud_str[1:].replace('%', '')
        return (float(val), float('inf'))
    if '-' in fraud_str:
        low, high = fraud_str.split('-')
        return (float(low.replace('%', '')), float(high.replace('%', '')))
    return None

def match_rule(rule, payment, merchant_mcc, merchant_account_type, merchant_capture_delay_mapped, monthly_volume, monthly_fraud_rate):
    # card_scheme
    if rule['card_scheme'] is not None and rule['card_scheme'] != payment['card_scheme']:
        return False
    # account_type
    if rule['account_type'] and merchant_account_type not in rule['account_type']:
        return False
    # capture_delay
    if rule['capture_delay'] is not None and rule['capture_delay'] != merchant_capture_delay_mapped:
        return False
