    if rule['monthly_volume'] is not None:
        range_val = parse_volume(rule['monthly_volume'])
        if not (range_val[0] <= monthly_volume < range_val[1]):
            return False
    # monthly_fraud_level
    if rule['monthly_fraud_level'] is not None:
        range_val = parse_fraud(rule['monthly_fraud_level'])
